import React, { useState, useEffect } from 'react';
import api from '../api';

function CarForm({ onSubmit, editingItem, onCancelEdit }) {

    const [carName, setCarName] = useState('');
    const [plateNumber, setPlateNumber] = useState('');
    const [brand, setBrand] = useState('');
    const [model, setModel] = useState('');
    const [manufactureYear, setManufactureYear] = useState('');
    const [rentalPricePerDay, setRentalPricePerDay] = useState('');
    const [status, setStatus] = useState('Available');
    const [branchId, setBranchId] = useState('');
    const [branches, setBranches] = useState([]);

    useEffect(function() {

        api.findAllBranches().then(function(response) {
            setBranches(response.data);
        }).catch(function() {});

    }, []);

    useEffect(function() {

        if (editingItem) {

            setCarName(editingItem.carName || '');
            setPlateNumber(editingItem.plateNumber || '');
            setBrand(editingItem.brand || '');
            setModel(editingItem.model || '');
            setManufactureYear(editingItem.manufactureYear || '');
            setRentalPricePerDay(editingItem.rentalPricePerDay || '');
            setStatus(editingItem.status || 'Available');
            setBranchId(editingItem.branchId || '');

        } else {

            setCarName('');
            setPlateNumber('');
            setBrand('');
            setModel('');
            setManufactureYear('');
            setRentalPricePerDay('');
            setStatus('Available');
            setBranchId('');

        }

    }, [editingItem]);

    function handleSubmit(e) {

        e.preventDefault();

        const yearValue = parseInt(manufactureYear) || 0;
        const priceValue = parseFloat(rentalPricePerDay) || 0;

        const data = {
            carName: carName,
            plateNumber: plateNumber,
            brand: brand,
            model: model,
            manufactureYear: yearValue,
            rentalPricePerDay: priceValue,
            status: status,
            branchId: branchId ? parseInt(branchId) : null
        };

        onSubmit(data);

        if (!editingItem) {

            setCarName('');
            setPlateNumber('');
            setBrand('');
            setModel('');
            setManufactureYear('');
            setRentalPricePerDay('');
            setStatus('Available');
            setBranchId('');

        }

    }

    return (

        <div style={{ background: '#fff', borderRadius: '16px', padding: '1.5rem', boxShadow: '0 4px 16px rgba(0,0,0,0.08)', border: '1px solid #e5e7eb' }}>

            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1.2rem', paddingBottom: '0.8rem', borderBottom: '3px solid #fbbf24' }}>

                <h2 style={{ margin: 0, fontSize: '1.1rem', color: '#1a1a2e' }}>
                    {editingItem ? 'Edit Car Details' : 'Add New Car for Rent'}
                </h2>

            </div>

            <form onSubmit={handleSubmit}>

                <div style={{ marginBottom: '0.8rem' }}>

                    <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                        Car Name
                    </label>

                    <input type="text"
                        value={carName}
                        onChange={function(e) { setCarName(e.target.value); }}
                        required
                        placeholder="e.g. Toyota Axio"
                        style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                </div>

                <div style={{ marginBottom: '0.8rem' }}>

                    <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                        Plate Number
                    </label>

                    <input type="text"
                        value={plateNumber}
                        onChange={function(e) { setPlateNumber(e.target.value); }}
                        required
                        placeholder="e.g. TZA-101X"
                        style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.8rem', marginBottom: '0.8rem' }}>

                    <div>

                        <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                            Brand
                        </label>

                        <select value={brand}
                            onChange={function(e) { setBrand(e.target.value); }}
                            required
                            style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', background: '#fff', boxSizing: 'border-box' }}>

                            <option value="">Select</option>
                            <option value="Toyota">Toyota</option>
                            <option value="Honda">Honda</option>
                            <option value="Suzuki">Suzuki</option>
                            <option value="Nissan">Nissan</option>
                            <option value="Mitsubishi">Mitsubishi</option>
                            <option value="BMW">BMW</option>
                            <option value="Mercedes">Mercedes</option>

                        </select>

                    </div>

                    <div>

                        <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                            Model
                        </label>

                        <input type="text"
                            value={model}
                            onChange={function(e) { setModel(e.target.value); }}
                            required
                            placeholder="e.g. Axio"
                            style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                    </div>

                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.8rem', marginBottom: '0.8rem' }}>

                    <div>

                        <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                            Manufacture Year
                        </label>

                        <input type="number"
                            value={manufactureYear}
                            onChange={function(e) { setManufactureYear(e.target.value); }}
                            required
                            placeholder="2024"
                            style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                    </div>

                    <div>

                        <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                            Rental Price/Day (TSh)
                        </label>

                        <input type="number"
                            value={rentalPricePerDay}
                            onChange={function(e) { setRentalPricePerDay(e.target.value); }}
                            required
                            placeholder="45000"
                            style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                    </div>

                </div>

                <div style={{ marginBottom: '1.2rem' }}>

                    <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                        Status
                    </label>

                    <select value={status}
                        onChange={function(e) { setStatus(e.target.value); }}
                        style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', background: '#fff', boxSizing: 'border-box' }}>

                        <option value="Available">Available</option>
                        <option value="Rented">Rented</option>
                        <option value="Under Maintenance">Under Maintenance</option>

                    </select>

                </div>

                <div style={{ marginBottom: '1.2rem' }}>

                    <label style={{ color: '#374151', fontSize: '0.85rem', fontWeight: 500, display: 'block', marginBottom: '0.25rem' }}>
                        Branch
                    </label>

                    <select value={branchId}
                        onChange={function(e) { setBranchId(e.target.value); }}
                        style={{ width: '100%', padding: '0.6rem 0.8rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', background: '#fff', boxSizing: 'border-box' }}>

                        <option value="">No Branch</option>
                        {branches.map(function(branch) {
                            return (
                                <option key={branch.id} value={branch.id}>
                                    {branch.name} - {branch.location}
                                </option>
                            );
                        })}

                    </select>

                </div>

                <div style={{ display: 'flex', gap: '0.75rem' }}>

                    <button type="submit"
                        style={{ flex: 1, padding: '0.65rem', background: '#fbbf24', color: '#1a1a2e', border: 'none', borderRadius: '8px', fontWeight: 700, cursor: 'pointer', fontSize: '0.95rem' }}>
                        {editingItem ? 'Update Car' : 'Add to Inventory'}
                    </button>

                    {editingItem && (

                        <button type="button" onClick={onCancelEdit}
                            style={{ padding: '0.65rem 1.2rem', background: '#f3f4f6', color: '#374151', border: '1px solid #d1d5db', borderRadius: '8px', fontWeight: 500, cursor: 'pointer' }}>
                            Cancel
                        </button>

                    )}

                </div>

            </form>

        </div>

    );

}

export default CarForm;
